CREATE TABLE growth_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, semester_id uuid NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, weight_kg numeric(5,2) NOT NULL CHECK(weight_kg>=0), height_cm numeric(5,2) NOT NULL CHECK(height_cm>=0), head_circumference_cm numeric(5,2), UNIQUE(student_id,semester_id));
CREATE TABLE attendance_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, semester_id uuid NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, sick_days integer NOT NULL DEFAULT 0 CHECK(sick_days>=0), permission_days integer NOT NULL DEFAULT 0 CHECK(permission_days>=0), unexcused_days integer NOT NULL DEFAULT 0 CHECK(unexcused_days>=0), UNIQUE(student_id,semester_id));
CREATE TABLE extracurricular_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, semester_id uuid NOT NULL REFERENCES semesters(id) ON DELETE CASCADE, activity_name varchar(160) NOT NULL, grade char(1) NOT NULL CHECK(grade IN ('A','B','C','D')), UNIQUE(student_id,semester_id,activity_name));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['growth_records','attendance_summaries','extracurricular_records'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I ON %I USING (school_id = NULLIF(current_setting(''app.school_id'',true),'''')::uuid) WITH CHECK (school_id = NULLIF(current_setting(''app.school_id'',true),'''')::uuid)',t||'_isolation',t); END LOOP; END $$;
GRANT SELECT, INSERT, UPDATE, DELETE ON growth_records, attendance_summaries, extracurricular_records TO ramu_app;
